            ["Welcome to Lootified"] = "欢迎使用Lootified",
            ["Welcome to Lootified! How should the window look?"] = "欢迎使用Lootified！窗口应该是什么外观？",
            ["Welcome to the Database"] = "欢迎使用数据库",
            ["What I wear"] = "我的装备",
            ["What is collected so far is saved with the next /reload."] = "已收集的内容将在下次/reload时保存。",
            ["What one more point is worth"] = "每多1点的价值",
            ["What you wear"] = "你的装备",
            ["What you wear, your Best in Slot sheet and your own sets side by side, all in the same fights."] = "你的装备、你的BiS表和你的自定义套装并列对比，战斗条件完全相同。",
